const tasks = await query('com.example.type.task', { status: 'open' });
print('open task count: ' + tasks.length);
for (const t of tasks) {
  print(JSON.stringify(Object.keys(t)));
  break;
}
for (const t of tasks) {
  print((t.title ?? '(no title)') + ' | priority=' + JSON.stringify(t.priority));
}

